# @freelang/web-forge

FreeLang Native Web Framework - SSG/SSR engine

**Zero npm dependencies** - Uses only Node.js built-in modules

## Features

- ✅ Static Site Generation (SSG)
- ✅ Server-Side Rendering (SSR)
- ✅ Template engine with components
- ✅ 21+ built-in functions
- ✅ Layout composition
- ✅ Partial templates
- ✅ Data-driven pages
- ✅ Asset pipeline
- ✅ Markdown support

## Installation

```bash
npm install @freelang/web-forge
```

## Usage

### Static Site Generation

```javascript
const { createSite, definePages } = require('@freelang/web-forge');

const site = createSite({
  outputDir: './dist',
  sourceDir: './src/pages',
  assetsDir: './src/assets',
  layoutsDir: './src/layouts'
});

// Define pages
const pages = definePages({
  'index.html': {
    template: 'home.html',
    data: { title: 'Home', description: 'Welcome' }
  },
  'about.html': {
    template: 'about.html',
    data: { title: 'About Us' }
  },
  'blog/post-1.html': {
    template: 'blog-post.html',
    data: require('./blog-data.json')
  }
});

await site.generate(pages);
console.log('✅ Site generated');
```

### Server-Side Rendering

```javascript
const { createRenderer } = require('@freelang/web-forge');

const renderer = createRenderer({
  layoutsDir: './src/layouts',
  componentsDir: './src/components',
  cacheTemplates: true
});

// Express route example
app.get('/page/:slug', async (req, res) => {
  const html = await renderer.render('page.html', {
    title: 'Dynamic Page',
    slug: req.params.slug,
    content: await fetchPageContent(req.params.slug)
  });

  res.send(html);
});
```

### Template System

```html
<!-- layouts/base.html -->
<!DOCTYPE html>
<html>
<head>
  <title>{{ title }}</title>
</head>
<body>
  {{ include('partials/header') }}
  <main>
    {{ content }}
  </main>
  {{ include('partials/footer') }}
</body>
</html>
```

### Components

```html
<!-- components/button.html -->
<button class="btn btn-{{ type }}">
  {{ label }}
</button>

<!-- Usage -->
{{ component('button', { type: 'primary', label: 'Click me' }) }}
```

### Template Variables

```javascript
const page = {
  title: 'My Page',
  items: [
    { id: 1, name: 'Item 1' },
    { id: 2, name: 'Item 2' }
  ],
  published: true
};

// Template
<h1>{{ title }}</h1>
{{ if published }}
  <span class="published">Published</span>
{{ endif }}

<ul>
{{ foreach items as item }}
  <li>{{ item.name }}</li>
{{ endforeach }}
</ul>
```

### Markdown Pages

```javascript
const { createSite, parseMarkdown } = require('@freelang/web-forge');

const pages = definePages({
  'blog/getting-started.html': {
    source: 'blog/getting-started.md',
    template: 'blog-post.html',
    parser: parseMarkdown,
    data: {
      author: 'John Doe',
      date: '2024-01-15'
    }
  }
});
```

### Data Transforms

```javascript
const { defineTransform } = require('@freelang/web-forge');

const dateFormat = defineTransform('date', (value, format) => {
  const date = new Date(value);
  return date.toLocaleDateString(format || 'en-US');
});

// In template
<p>Published: {{ published_at | date('en-US') }}</p>
```

### Asset Pipeline

```javascript
const site = createSite({
  outputDir: './dist',
  assetPipeline: {
    css: {
      minify: true,
      sourceMap: false
    },
    js: {
      minify: true,
      bundle: true
    },
    images: {
      optimize: true,
      formats: ['webp', 'jpg', 'png']
    }
  }
